do $publish$ declare current_html text; item jsonb; begin
select html into current_html from public.frontend_snapshots where key='stable-v10-clean' for update;
if md5(current_html) <> '1421559cc9145e931b6ff9682bec104e' then raise exception 'Admin snapshot changed; review before publishing'; end if;
insert into public.frontend_snapshots(key,html) values ('backup-20261009-before-application-care-split',current_html) on conflict (key) do nothing;
for item in select value from jsonb_array_elements($replacements$[{"before":"interest_reason,dog_info,staff_note","after":"interest_reason,dog_info,dog_allergies,dog_temperament,staff_note"},{"before":"owner_phone,notes,breed,weight_kg,sex","after":"owner_phone,notes,allergies,temperament,breed,weight_kg,sex"},{"before":"s.dog_breed,s.dog_info","after":"s.dog_breed,s.dog_info,s.dog_allergies,s.dog_temperament"},{"before":"<textarea id=\"newDogNotes\" class=\"input\" rows=\"4\" placeholder=\"Poznámky – alergie, povaha, zdravotné obmedzenia, dôležité info\"></textarea>","after":"<div><label class=\"muted small\" for=\"newDogAllergies\">Alergie a zdravotné obmedzenia</label><textarea id=\"newDogAllergies\" class=\"input\" rows=\"3\" maxlength=\"3000\"></textarea></div><div><label class=\"muted small\" for=\"newDogTemperament\">Povaha a ďalšie informácie</label><textarea id=\"newDogTemperament\" class=\"input\" rows=\"3\" maxlength=\"3000\"></textarea></div><div><label class=\"muted small\" for=\"newDogNotes\">Interné poznámky / pôvodné informácie</label><textarea id=\"newDogNotes\" class=\"input\" rows=\"4\" placeholder=\"Poznámky personálu alebo pôvodný spoločný text prihlášky\"></textarea></div>"},{"before":"<textarea id=\"introNotes\" class=\"input\" rows=\"3\" placeholder=\"Poznámka – čo ste si dohodli alebo dôležité informácie\"></textarea>","after":"<div><label class=\"muted small\" for=\"introAllergies\">Alergie a zdravotné obmedzenia</label><textarea id=\"introAllergies\" class=\"input\" rows=\"3\" maxlength=\"3000\"></textarea></div><div><label class=\"muted small\" for=\"introTemperament\">Povaha a ďalšie informácie</label><textarea id=\"introTemperament\" class=\"input\" rows=\"3\" maxlength=\"3000\"></textarea></div><textarea id=\"introNotes\" class=\"input\" rows=\"3\" placeholder=\"Poznámka – čo ste si dohodli alebo pôvodné informácie\"></textarea>"},{"before":"<div><label class=\"muted small\">Poznámka</label><textarea id=\"editIntroNotes\"","after":"<div><label class=\"muted small\" for=\"editIntroAllergies\">Alergie a zdravotné obmedzenia</label><textarea id=\"editIntroAllergies\" class=\"input\" rows=\"3\" maxlength=\"3000\">${esc(v.allergies??introSourceSubmissionV62(v)?.dog_allergies??'')}</textarea></div><div><label class=\"muted small\" for=\"editIntroTemperament\">Povaha a ďalšie informácie</label><textarea id=\"editIntroTemperament\" class=\"input\" rows=\"3\" maxlength=\"3000\">${esc(v.temperament??introSourceSubmissionV62(v)?.dog_temperament??'')}</textarea></div><div><label class=\"muted small\">Poznámka / pôvodné informácie</label><textarea id=\"editIntroNotes\""},{"before":"if(s.dog_info)parts.push('Informácie o psíkovi: '+s.dog_info);","after":"if(s.dog_allergies==null&&s.dog_temperament==null&&s.dog_info)parts.push('Pôvodné informácie o psíkovi: '+s.dog_info);"},{"before":"$('introNotes').value=webSubmissionIntroNotes(s);","after":"$('introNotes').value=webSubmissionIntroNotes(s);\n  $('introAllergies').value=s.dog_allergies??'';\n  $('introTemperament').value=s.dog_temperament??'';"},{"before":"$('newDogNotes').value=s.dog_info||'';","after":"$('newDogAllergies').value=s.dog_allergies??'';\n  $('newDogTemperament').value=s.dog_temperament??'';\n  $('newDogNotes').value=s.dog_allergies==null&&s.dog_temperament==null?s.dog_info||'':'';"},{"before":"$('newDogNotes').value=intro.notes||source?.dog_info||'';","after":"$('newDogAllergies').value=intro.allergies??source?.dog_allergies??'';\n    $('newDogTemperament').value=intro.temperament??source?.dog_temperament??'';\n    $('newDogNotes').value=intro.notes||(source?.dog_allergies==null&&source?.dog_temperament==null?source?.dog_info:'')||'';"},{"before":"notes:$('newDogNotes').value.trim()||null,allergies:sourceSubmissionId?(state.webSubmissions||[]).find(s=>Number(s.id)===Number(sourceSubmissionId))?.dog_info||null:null,active:true","after":"notes:$('newDogNotes').value.trim()||null,allergies:$('newDogAllergies').value.trim()||null,temperament:$('newDogTemperament').value.trim()||null,active:true"},{"before":"owner_phone:phone,notes,breed,weight_kg","after":"owner_phone:phone,notes,allergies:$('introAllergies').value.trim(),temperament:$('introTemperament').value.trim(),breed,weight_kg"},{"before":"const payload={dog_name,owner_name,owner_phone,notes,breed,weight_kg","after":"const payload={dog_name,owner_name,owner_phone,notes,allergies:$('editIntroAllergies').value.trim(),temperament:$('editIntroTemperament').value.trim(),breed,weight_kg"},{"before":"const dogInfo=isApplication&&s.dog_info\n    ?'<div class=\"history-row\"><div class=\"muted small\">Informácie o psíkovi</div><div style=\"margin-top:4px;white-space:pre-wrap\">'+esc(s.dog_info)+'</div></div>'\n    :'';","after":"const dogInfo=isApplication?webSubmissionCareHtml(s):'';"},{"before":"(s.dog_info?'<div class=\"intro-source-section-v62\"><strong>Informácie o psíkovi</strong><p class=\"intro-source-text-v62\">'+esc(s.dog_info)+'</p></div>':'')+","after":"webSubmissionCareHtml(s)+"},{"before":"function webSubmissionIntroNotes(s){","after":"function webSubmissionCareHtml(s){\n  const row=(label,value)=>'<div class=\"history-row\"><div class=\"muted small\">'+esc(label)+'</div><div style=\"margin-top:4px;white-space:pre-wrap;overflow-wrap:anywhere\">'+esc(value||'—')+'</div></div>';\n  if(s.dog_allergies!=null||s.dog_temperament!=null)return row('Alergie a zdravotné obmedzenia',s.dog_allergies)+row('Povaha a ďalšie informácie',s.dog_temperament);\n  return s.dog_info?row('Pôvodné informácie o psíkovi',s.dog_info):'';\n}\nfunction webSubmissionIntroNotes(s){"}]$replacements$::jsonb) loop
if position(item->>'before' in current_html)=0 then raise exception 'Patch target missing'; end if;
current_html := replace(current_html,item->>'before',item->>'after');
end loop;
update public.frontend_snapshots set html=current_html where key='stable-v10-clean';
end; $publish$;
